# dev server on port 18081 (the owner's own server keeps 18080); the Claude emulator uses release/HelloBro-for-127.0.0.1-18081.apk
# every request + full reply also goes to %TEMP%\hb\replies.log (HB_REPLY_LOG; the emulator log cuts long replies)
powershell -NoProfile -Command "Get-NetTCPConnection -LocalPort 18081 -State Listen -ErrorAction SilentlyContinue | ForEach-Object { Stop-Process -Id \$_.OwningProcess -Force }; Start-Sleep 1; \$env:PORT='18081'; \$env:HB_REPLY_LOG=(Join-Path \$env:TEMP 'hb\replies.log'); Start-Process -FilePath node -ArgumentList 'server\server.js' -WorkingDirectory 'C:\Users\dj199\Desktop\HelloBroServer' -RedirectStandardOutput \"\$env:TEMP\hb\server.log\" -RedirectStandardError \"\$env:TEMP\hb\server.err\" -WindowStyle Hidden; Start-Sleep 2"
